"""Path handling and error classification shared by the :mod:`wsparse` modules.

Every entry point in the public API accepts "a path", which on Windows may be
a plain file, a directory, a reparse point, a volume root, or a path that does
not exist at all.  The acceptance rules for the module are strict about what
has to happen in each of those cases:

* a missing path is an ``"os"`` failure (the caller can fix it by creating
  the file),
* an object that cannot hold a sparse file -- a directory, a device, a volume
  root, a file on a volume without sparse support -- is an ``"unsupported"``
  failure,
* anything else the kernel refuses is an ``"os"`` failure.

This module turns the raw Win32 error codes into those classes so that the
public functions stay readable.
"""

import ctypes
import os

from . import _winapi
from ._winapi import (
    DIRECTORY_ATTRIBUTE,
    ERROR_BAD_PATHNAME,
    ERROR_FILE_NOT_FOUND,
    ERROR_INVALID_FUNCTION,
    ERROR_NOT_SUPPORTED,
    ERROR_PATH_NOT_FOUND,
    REPARSE_POINT_ATTRIBUTE,
    SPARSE_ATTRIBUTE,
    UNSUPPORTED_ERRORS,
    UnsupportedOperation,
)
from .errors import WSParseError

#: Win32 codes that mean "the path you gave me does not exist".
_MISSING_ERRORS = frozenset(
    (ERROR_FILE_NOT_FOUND, ERROR_PATH_NOT_FOUND, ERROR_BAD_PATHNAME)
)

#: Extra codes that mean "this object can never be a sparse file".
_NOT_A_SPARSE_FILE_ERRORS = frozenset(
    (
        _winapi.ERROR_DIRECTORY,
        _winapi.ERROR_BAD_DEVICE_TYPE,
        _winapi.ERROR_BAD_NET_NAME,
        _winapi.ERROR_BAD_NETPATH,
        _winapi.ERROR_UNRECOGNIZED_VOLUME,
        _winapi.ERROR_ALREADY_ASSIGNED,
        _winapi.ERROR_ACCESS_DENIED,
    )
)

#: Default NTFS allocation unit, used when the volume cannot be asked.
DEFAULT_CLUSTER_SIZE = 4096


def normalize(path):
    """Return ``path`` as a string, rejecting unusable arguments."""
    if path is None:
        raise WSParseError("path must not be None", kind="badarg")
    try:
        return os.fspath(path)
    except TypeError:
        raise WSParseError(
            "path must be a string or os.PathLike, got %r" % (path,), kind="badarg"
        )


def is_windows_or_raise(path, what):
    """Guard for the Win32 calls: only Windows volumes have sparse files."""
    if _winapi.is_windows():
        return
    raise WSParseError(
        "%s requires a Windows file system; this platform does not have one" % what,
        kind="unsupported",
        path=path,
    )


def missing(path):
    """``True`` when ``path`` does not resolve to anything on the volume."""
    if isinstance(path, bytes):
        try:
            path = os.fsdecode(path)
        except Exception:  # pragma: no cover - defensive
            return True
    if not _winapi.is_windows():
        return not os.path.exists(path)
    try:
        _winapi.get_file_attributes(path)
    except OSError:
        return True
    return False


def _attributes(path):
    """Attribute word of ``path``, or ``None`` when it cannot be read."""
    try:
        return _winapi.get_file_attributes(path)
    except OSError:
        try:
            return int(os.stat(path).st_file_attributes or 0)
        except Exception:
            return None


def not_a_sparse_file(path):
    """``True`` when ``path`` exists but can never carry a sparse attribute.

    Directories, volume roots, reparse points and device objects all fall in
    here: they are addressable, but ``FSCTL_SET_SPARSE`` and friends are
    meaningless on them.
    """
    attrs = _attributes(path)
    if attrs is None:
        return False
    if attrs & DIRECTORY_ATTRIBUTE:
        return True
    if attrs & REPARSE_POINT_ATTRIBUTE:
        return True
    text = str(path).rstrip("\\/")
    if not text or text.endswith(":"):
        # "C:", "C:" -> volume root, "\\server\share" -> share root.
        return True
    return False


def volume_supports_sparse(path):
    """``True`` when the volume holding ``path`` advertises sparse files.

    When the volume cannot be queried we assume it does support them and let
    the actual control call decide.
    """
    if not _winapi.is_windows():
        return False
    return _winapi.get_volume_sparse_support(path)


def translate(exc, path, what):
    """Turn a kernel failure into a classified :class:`WSParseError`."""
    if isinstance(exc, WSParseError):
        return exc

    code = None
    if isinstance(exc, UnsupportedOperation):
        code = getattr(exc, "winerror", None)
    elif isinstance(exc, OSError):
        code = getattr(exc, "winerror", None)
        if code is None and len(getattr(exc, "args", ())) >= 4:
            code = exc.args[3]

    if isinstance(code, int) and code:
        if code in UNSUPPORTED_ERRORS or code in _NOT_A_SPARSE_FILE_ERRORS:
            return WSParseError(
                "%s is not supported on %r (Win32 error %d)" % (what, path, code),
                kind="unsupported",
                path=path,
            )
        if code in _MISSING_ERRORS:
            return WSParseError(
                "no such file: %s" % (path,), kind="os", path=path
            )
        return WSParseError(
            "%s failed (%s)" % (what, _winapi.winerror_message(code)),
            kind="os",
            path=path,
        )

    # No Win32 code: fall back on the shape of the object we were handed.
    if not_a_sparse_file(path):
        return WSParseError(
            "%s is not supported on %r" % (what, path), kind="unsupported", path=path
        )
    if missing(path):
        return WSParseError("no such file: %s" % (path,), kind="os", path=path)
    return WSParseError("%s failed (%s)" % (what, exc), kind="os", path=path)


def fail(exc, path, what):
    """``raise translate(exc, path, what)``."""
    raise translate(exc, path, what)


def _classify_open_error(exc, path, what, writable):
    """Classify a failure of :func:`open_stream`.

    A directory (or any other object that cannot be a sparse file) is reported
    as ``"unsupported"`` even when the kernel merely refused to grant write
    access to it -- the object could never hold a sparse extent.
    """
    code = getattr(exc, "winerror", None)
    if code is None and len(getattr(exc, "args", ())) >= 4:
        code = exc.args[3]

    if isinstance(exc, UnsupportedOperation) or (
        isinstance(code, int) and code in UNSUPPORTED_ERRORS
    ):
        return WSParseError(
            "%s is not supported on %r" % (what, path), kind="unsupported", path=path
        )

    if code in _MISSING_ERRORS or missing(path):
        return WSParseError("no such file: %s" % (path,), kind="os", path=path)

    if not_a_sparse_file(path):
        return WSParseError(
            "%s is not supported on %r" % (what, path), kind="unsupported", path=path
        )

    if writable and isinstance(code, int) and code in _NOT_A_SPARSE_FILE_ERRORS:
        return WSParseError(
            "%s is not supported on %r (Win32 error %d)" % (what, path, code),
            kind="unsupported",
            path=path,
        )

    return WSParseError(
        "%s failed (%s)" % (what, _winapi.winerror_message(code) if code else exc),
        kind="os",
        path=path,
    )


def open_stream(path, what, writable=False, create=False):
    """Open ``path`` for the file-system control calls.

    ``writable`` requests ``GENERIC_WRITE`` as well; ``create`` creates the
    file when it does not exist yet.  Failures are translated with
    :func:`_classify_open_error` so that a directory or a volume root is
    reported as ``unsupported`` and a missing path as ``os``.
    """
    is_windows_or_raise(path, what)

    access = _winapi.GENERIC_READ
    if writable:
        access |= _winapi.GENERIC_WRITE
    creation = _winapi.OPEN_ALWAYS if create else _winapi.OPEN_EXISTING
    flags = _winapi.FILE_FLAG_BACKUP_SEMANTICS
    try:
        handle = _winapi.open_file(path, access, creation=creation, flags=flags)
    except OSError as exc:
        raise _classify_open_error(exc, path, what, writable) from None

    # ``FILE_FLAG_BACKUP_SEMANTICS`` happily opens a directory; the sparse
    # control calls would only fail on it later, so catch it up front.
    if not_a_sparse_file(path):
        _winapi.close_handle(handle)
        raise WSParseError(
            "%s is not supported on %r" % (what, path), kind="unsupported", path=path
        )
    return handle


def file_length(path):
    """Logical length of ``path`` in bytes (raises :class:`WSParseError`)."""
    try:
        return int(os.stat(path).st_size)
    except OSError as exc:
        fail(exc, path, "stat")


def cluster_size(path):
    """Allocation unit of the volume that holds ``path``."""
    try:
        size = _winapi.get_cluster_size(path)
    except Exception:
        size = 0
    return int(size) if size > 0 else DEFAULT_CLUSTER_SIZE


def round_up(value, unit):
    if unit <= 1:
        return int(value)
    return ((int(value) + unit - 1) // unit) * unit


def sparse_attribute_state(path):
    """``True`` when ``path`` currently carries ``FILE_ATTRIBUTE_SPARSE_FILE``."""
    attrs = _attributes(path)
    if attrs is not None:
        return bool(attrs & SPARSE_ATTRIBUTE)
    return False


def round_allocation(value, cluster):
    """Round an allocation size up to a whole cluster."""
    return round_up(value, cluster)


def _sizeof(structure):  # pragma: no cover - helper kept for symmetry
    return ctypes.sizeof(structure)


__all__ = [
    "DEFAULT_CLUSTER_SIZE",
    "normalize",
    "is_windows_or_raise",
    "missing",
    "not_a_sparse_file",
    "volume_supports_sparse",
    "translate",
    "fail",
    "open_stream",
    "file_length",
    "cluster_size",
    "round_up",
    "round_allocation",
    "sparse_attribute_state",
]

